"""Soft-failing script moments and shared source-image geometry."""
from __future__ import annotations
import math
from PySide6.QtCore import QRectF, QPointF, Qt
from PySide6.QtGui import QColor, QFont, QPainter, QPainterPath, QPen
from .schema import frame_at

def validate_moments(package):
    words={w.index:w for w in package.words}; scenes={s.id:s for s in package.scenes}
    valid=[]; notices=[]; ids=set()
    values=package.pro.get('moments',[])
    if not isinstance(values,list):return [],['$.moments skipped: expected an array.']
    for i,item in enumerate(values):
        path=f'$.moments[{i}]'
        try:
            if not isinstance(item,dict):raise ValueError('expected an object')
            ident=item.get('id',str(i)); kind=item.get('type')
            if not isinstance(ident,str) or ident in ids:raise ValueError('id must be unique text')
            ids.add(ident)
            start=item.get('word_start_index'); end=item.get('word_end_index')
            if isinstance(start,bool) or isinstance(end,bool) or start not in words or end not in words or end<start:
                raise ValueError('word indices must reference an ordered range in words')
            first=frame_at(words[start].start,package.fps);last=frame_at(words[end].end,package.fps)
            if last<=first:raise ValueError('word timing must span at least one frame')
            if kind=='DATE_CARD':
                if item.keys()-{'id','type','text','word_start_index','word_end_index','dim'}:raise ValueError('unknown DATE_CARD field')
                if not isinstance(item.get('text'),str) or not 1<=len(item['text'])<=80:raise ValueError('text must be 1–80 characters')
                dim=item.get('dim',.65)
                if isinstance(dim,bool) or not isinstance(dim,(int,float)) or not math.isfinite(dim) or not 0<=dim<=.8:raise ValueError('dim must be 0–0.8')
            elif kind=='CIRCLE':
                if item.keys()-{'id','type','scene_id','box','word_start_index','word_end_index'}:raise ValueError('unknown CIRCLE field')
                scene=scenes.get(item.get('scene_id')); box=item.get('box')
                if not scene:raise ValueError('scene_id must exist')
                if not isinstance(box,list) or len(box)!=4 or any(isinstance(v,bool) or not isinstance(v,(int,float)) or not math.isfinite(v) for v in box):raise ValueError('box must be [x,y,width,height] in source-image coordinates')
                x,y,w,h=box
                if x<0 or y<0 or w<.03 or h<.03 or x+w>1 or y+h>1 or w*h>.2:raise ValueError('box must fit source image, each side ≥0.03, area ≤0.20')
                if first<scene.first_frame or last>scene.end_frame:raise ValueError('word range must be inside the referenced scene')
            else:raise ValueError('type must be DATE_CARD or CIRCLE')
            valid.append({**item,'id':ident,'first_frame':first,'end_frame':last})
        except (ValueError,TypeError,KeyError) as exc:notices.append(f'{path} skipped: {exc}.')
    return valid,notices

def destination(crop: QRectF,width: int,height: int,settings) -> QRectF:
    if settings.aspect_policy in {'FIT','BLUR_FILL'} or settings.aspect_policy is None and settings.framing=='Fit Entire Image':
        scale=min(width/crop.width(),height/crop.height())
        return QRectF((width-crop.width()*scale)/2,(height-crop.height()*scale)/2,crop.width()*scale,crop.height()*scale)
    return QRectF(0,0,width,height)

def map_box(box,image,crop,dest):
    x,y,w,h=box
    source=QRectF(x*image.width(),y*image.height(),w*image.width(),h*image.height())
    return QRectF(dest.x()+(source.x()-crop.x())*dest.width()/crop.width(),
                  dest.y()+(source.y()-crop.y())*dest.height()/crop.height(),
                  source.width()*dest.width()/crop.width(),source.height()*dest.height()/crop.height())

def circle_visible(moment,compositor,plan):
    image=compositor._image(plan.image_id);x,y,w,h=moment['box']
    box=QRectF(x*image.width(),y*image.height(),w*image.width(),h*image.height())
    # Check every frame because easing and focus clamping may peak between endpoints.
    return all(compositor._motion(plan,f,image).contains(box) for f in range(moment['first_frame'],moment['end_frame']))

def draw_circle(image,moment,frame,fps):
    x,y,w,h=moment['box']; rect=QRectF(x*image.width(),y*image.height(),w*image.width(),h*image.height())
    p=QPainter(image);p.setRenderHint(QPainter.Antialiasing)
    p.setPen(QPen(QColor('#FF3434'),max(2,image.width()*.004),Qt.SolidLine,Qt.RoundCap));p.setBrush(Qt.NoBrush)
    progress=min(1,(frame-moment['first_frame']+1)/max(1,round(.4*fps)))
    path=QPainterPath();path.arcMoveTo(rect,90);path.arcTo(rect,90,-360*progress);p.drawPath(path);p.end()

def draw_date(image,moment,frame,fps):
    fade=max(1,round(.15*fps));alpha=min(1,(frame-moment['first_frame']+1)/fade,(moment['end_frame']-frame)/fade)
    p=QPainter(image);p.setRenderHint(QPainter.TextAntialiasing);p.setOpacity(alpha)
    p.fillRect(image.rect(),QColor(0,0,0,round(255*moment.get('dim',.65))))
    font=QFont('Inter');font.setBold(True);font.setPixelSize(max(12,round(min(image.width()*.13,image.height()*.085))))
    p.setFont(font);p.setPen(QColor('#FFFFFF'))
    rect=QRectF(image.width()*.08,image.height()*.22,image.width()*.84,image.height()*.48)
    from PySide6.QtGui import QFontMetricsF
    while font.pixelSize()>12 and (QFontMetricsF(font).boundingRect(rect,Qt.AlignCenter|Qt.TextWordWrap,moment['text']).height()>rect.height()):
        font.setPixelSize(font.pixelSize()-2)
    p.setFont(font);p.drawText(rect,Qt.AlignCenter|Qt.TextWordWrap,moment['text']);p.end()

"""Shared visual language and non-blocking, reduced-motion-aware polish."""
import ctypes
import sys
from PySide6.QtCore import Qt, QPropertyAnimation, QEasingCurve, QTimer, QAbstractAnimation, QRect
from PySide6.QtWidgets import QPushButton, QLabel, QComboBox, QSlider, QDialog, QScrollArea, QWidget, QVBoxLayout

ACCENT='#ACE62D'
STYLE='''
QWidget { background:#0E1115; color:#E9EDF3; font-family:Inter; font-size:13px; }
QDialog, QMenu { background:#101419; }
QLabel { background:transparent; }
QLabel[muted="true"] { color:#8290A3; font-size:12px; }
QLabel[heading="true"] { font-size:18px; font-weight:600; }
QPushButton { background:#1D242D; border:1px solid #2A333E; border-radius:12px; padding:10px 14px; }
QPushButton:hover { background:#29333F; border-color:#4B5968; }
QPushButton:pressed { background:#344150; }
QPushButton:disabled { color:#627081; background:#161C24; }
QPushButton[primary="true"] { background:#ACE62D; color:#0C1603; border:none; font-weight:600; }
QPushButton[primary="true"]:hover { background:#BDFC45; }
QPushButton[primary="true"]:pressed { background:#8BBC1D; }
QPushButton:checked { border-color:#ACE62D; background:#202A20; }
QLineEdit, QTextEdit, QPlainTextEdit, QComboBox { background:#151B22; border:1px solid #29323C; border-radius:10px; padding:10px; selection-background-color:#435C22; }
QComboBox::drop-down { border:none; width:22px; }
QComboBox QAbstractItemView { background:#1D242D; selection-background-color:#36462A; padding:6px; }
QScrollArea { border:none; background:transparent; }
QScrollBar:vertical { background:#11161C; width:8px; border-radius:4px; }
QScrollBar::handle:vertical { background:#35414E; border-radius:4px; min-height:32px; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height:0; }
QSlider::groove:horizontal { height:4px; background:#2C3642; border-radius:2px; }
QSlider::sub-page:horizontal { background:#ACE62D; border-radius:2px; }
QSlider::handle:horizontal { background:#E3E9F0; width:12px; height:12px; margin:-4px 0; border-radius:6px; }
QTabWidget::pane { border:none; }
QTabBar::tab { background:#171D25; padding:12px 16px; color:#8999AD; }
QTabBar::tab:selected { background:#28313C; color:#F8FAFF; }
QMenuBar { background:#0E1115; padding:4px; }
QMenuBar::item { padding:6px 10px; border-radius:6px; }
QMenuBar::item:selected, QMenu::item:selected { background:#29333F; }
QMenu { border:1px solid #29323C; padding:6px; }
QMenu::item { padding:8px 22px; }
QProgressBar { border:none; background:#232D38; border-radius:6px; min-height:10px; text-align:center; }
QProgressBar::chunk { background:#ACE62D; border-radius:6px; }
QToolTip { background:#222C36; color:#F3F6FC; border:1px solid #45505D; padding:8px; }
'''

def reduced_motion():
    if sys.platform!='win32':return False
    value=ctypes.c_int(1)
    try:return not bool(ctypes.windll.user32.SystemParametersInfoW(0x1042,0,ctypes.byref(value),0) and value.value)
    except Exception:return True

def fade_window(widget,duration=220,scale=False):
    if reduced_motion():return
    old=getattr(widget,'_fade',None)
    if old:old.stop()
    widget.setWindowOpacity(0)
    anim=QPropertyAnimation(widget,b'windowOpacity',widget);anim.setDuration(duration)
    anim.setStartValue(0.0);anim.setEndValue(1.0);anim.setEasingCurve(QEasingCurve.OutCubic)
    widget._fade=anim;anim.start()
    if scale:
        end=widget.geometry();start=QRect(end);start.setSize(end.size()*.98);start.moveCenter(end.center())
        geometry=QPropertyAnimation(widget,b'geometry',widget);geometry.setDuration(duration);geometry.setStartValue(start);geometry.setEndValue(end);geometry.setEasingCurve(QEasingCurve.OutCubic)
        widget._scale=geometry;geometry.start()

def dark_titlebar(widget):
    if sys.platform=='win32':
        try:
            value=ctypes.c_int(1)
            ctypes.windll.dwmapi.DwmSetWindowAttribute(ctypes.c_void_p(int(widget.winId())),20,ctypes.byref(value),ctypes.sizeof(value))
        except Exception:pass

class Dialog(QDialog):
    def showEvent(self,event):
        super().showEvent(event);dark_titlebar(self);fade_window(self,180,True)

class ClickCombo(QComboBox):
    def wheelEvent(self,event):event.ignore()

class ClickSlider(QSlider):
    def __init__(self,parent=None):super().__init__(Qt.Horizontal,parent)
    def wheelEvent(self,event):event.ignore()

def button(text,callback=None,primary=False):
    b=QPushButton(text);b.setProperty('primary',primary)
    if callback:b.clicked.connect(callback)
    return b

def label(text,muted=False,heading=False):
    l=QLabel(text);l.setProperty('muted',muted);l.setProperty('heading',heading);l.setWordWrap(True);return l

def scroll(widget):
    s=QScrollArea();s.setWidgetResizable(True);s.setWidget(widget);s.setFrameShape(QScrollArea.NoFrame);return s

def human_time(seconds):
    seconds=max(0,int(seconds));return f'{seconds//60:02}:{seconds%60:02}' if seconds<3600 else f'{seconds//3600}:{seconds%3600//60:02}:{seconds%60:02}'

"""Transactional launch/import and focused export dialogs."""
from pathlib import Path
import json
import time
from PySide6.QtCore import QThread, Signal, QTimer, Qt, QPropertyAnimation, QEasingCurve
from PySide6.QtWidgets import (QWidget,QVBoxLayout,QHBoxLayout,QGridLayout,QLineEdit,QPlainTextEdit,
    QFileDialog,QDialogButtonBox,QProgressBar,QMessageBox,QApplication)
from ..product import Project, FORMATS, StageETA
from ..pro_spec import build_spec
from .common import Dialog,button,label,scroll,ClickCombo,human_time,reduced_motion
from .workers import ExportWorker

class ImportWorker(QThread):
    ready=Signal(object,object);failed=Signal(str)
    def __init__(self,project,parent=None):super().__init__(parent);self.project=project
    def run(self):
        try:
            p=self.project.validate();spec=build_spec(p.effective_package(),p.images,p.settings())
            if not self.isInterruptionRequested():self.ready.emit(p,spec)
        except Exception as exc:
            if not self.isInterruptionRequested():self.failed.emit(str(exc))

class LaunchDialog(Dialog):
    def __init__(self,parent=None,current=None,recents=()):
        super().__init__(parent);self.setWindowTitle('New project · Auto Timeline Sync 3.0');self.resize(920,620)
        self.setMinimumSize(600,420);self.result_project=None;self.spec=None;self.worker=None;self.revision=0;self.validated_revision=-1;self.error=''
        root=QHBoxLayout(self);root.setContentsMargins(24,24,24,24);root.setSpacing(24)
        recent=QWidget();recent.setMaximumWidth(200);r=QVBoxLayout(recent);r.setContentsMargins(0,0,0,0)
        r.addWidget(label('Auto Timeline\nSync',heading=True));r.addWidget(label('by Naimat · 3.0',True));r.addSpacing(24);r.addWidget(label('RECENT',True))
        for path in recents[:5]:
            b=button(Path(path).stem,lambda checked=False,path=path:self.open_project(path));b.setToolTip(path);r.addWidget(b)
        r.addStretch();r.addWidget(button('Open project…',self.open_project));root.addWidget(recent,1)
        body=QWidget();v=QVBoxLayout(body);v.setContentsMargins(0,0,0,0);v.setSpacing(16)
        v.addWidget(label('New project',heading=True));self.name=QLineEdit(current.name if current else 'Untitled project');self.name.setPlaceholderText('Project name');v.addWidget(self.name)
        self.fields={}
        for key,title in [('narration','Narration audio'),('image_folder','Numbered images'),('script','Script JSON'),('music','Background music · optional')]:
            row=QWidget();g=QGridLayout(row);g.setContentsMargins(0,0,0,0);g.addWidget(label(title),0,0)
            edit=QLineEdit();edit.setReadOnly(True);edit.setPlaceholderText('Choose file…' if key!='image_folder' else 'Choose folder…')
            g.addWidget(edit,1,0);g.addWidget(button('Choose',lambda checked=False,key=key:self.choose(key)),1,1)
            if key=='script':g.addWidget(button('Paste',self.paste_json),1,2)
            if key=='music':g.addWidget(button('×',lambda:self.set_field('music','')),1,2)
            self.fields[key]=edit;v.addWidget(row)
        self.script_text=current.script if current else '';self.source_name='Pasted JSON' if self.script_text else ''
        self.summary=label('Choose narration, numbered images and a script. Music is optional.',True);v.addWidget(self.summary)
        self.copy=button('Copy for ChatGPT',self.copy_error);self.copy.hide();v.addWidget(self.copy)
        actions=QHBoxLayout();actions.addStretch();actions.addWidget(button('Cancel',self.reject));self.create=button('Create Timeline',self.accept_project,True);self.create.setEnabled(False);actions.addWidget(self.create);v.addLayout(actions)
        root.addWidget(scroll(body),3)
        self.timer=QTimer(self);self.timer.setSingleShot(True);self.timer.setInterval(250);self.timer.timeout.connect(self.validate_async)
        if current:
            for key in ('narration','image_folder','music'):self.fields[key].setText(getattr(current,key))
            self.fields['script'].setText(self.source_name)
        for edit in self.fields.values():edit.textChanged.connect(self.changed)
        self.name.textChanged.connect(self.changed)
        if current:self.changed()

    def set_field(self,key,value):self.fields[key].setText(value)
    def choose(self,key):
        if key=='image_folder':path=QFileDialog.getExistingDirectory(self,'Numbered images')
        else:
            filters='JSON (*.json)' if key=='script' else 'Audio (*.mp3 *.wav *.m4a *.flac)'
            path,_=QFileDialog.getOpenFileName(self,'Choose '+key,'',filters)
        if not path:return
        if key=='script':
            try:self.script_text=Path(path).read_text(encoding='utf-8');self.source_name=path
            except Exception as exc:self.show_error(str(exc));return
        self.set_field(key,path)

    def paste_json(self):
        dialog=Dialog(self);dialog.setWindowTitle('Paste script JSON');dialog.resize(640,400);layout=QVBoxLayout(dialog)
        text=QPlainTextEdit(self.script_text or QApplication.clipboard().text());layout.addWidget(text)
        box=QDialogButtonBox(QDialogButtonBox.Ok|QDialogButtonBox.Cancel);box.accepted.connect(dialog.accept);box.rejected.connect(dialog.reject);layout.addWidget(box)
        if dialog.exec()==Dialog.Accepted:
            self.script_text=text.toPlainText();self.source_name='Pasted JSON';self.fields['script'].setText(self.source_name);self.changed()

    def changed(self):
        self.revision+=1;self.create.setEnabled(False);self.copy.hide();self.timer.start()

    def validate_async(self):
        if self.worker and self.worker.isRunning():self.worker.requestInterruption();return
        if not self.script_text or not self.fields['narration'].text() or not self.fields['image_folder'].text():return
        project=Project(self.name.text().strip() or 'Untitled project',self.fields['narration'].text(),self.fields['image_folder'].text(),self.script_text,self.fields['music'].text())
        revision=self.revision;self.summary.setText('Checking files and preparing your timeline…')
        self.worker=ImportWorker(project,self);worker=self.worker
        worker.ready.connect(lambda p,s:self.validated(revision,p,s));worker.failed.connect(self.show_error)
        worker.finished.connect(lambda:self.worker_finished(worker,revision));worker.start()

    def worker_finished(self,worker,revision):
        if self.worker is worker:self.worker=None
        worker.deleteLater()
        if revision!=self.revision and self.isVisible():self.timer.start()

    def validated(self,revision,project,spec):
        if revision!=self.revision:return
        self.result_project,self.spec=project,spec;self.validated_revision=revision
        p=project.package;self.summary.setText(f'✓ All files match: {len(p.scenes)} scenes · {len(p.captions)} captions · {human_time(p.audio_duration)} · {FORMATS[project.orientation][0]}')
        self.create.setEnabled(True);self.copy.hide()

    def show_error(self,message):
        self.error=f'ATS 3.0 import error\nJSON: {self.source_name or "not selected"}\n{message}\nExpected: one ATS_PACKAGE_V2 object matching the final narration and numbered images. Fix the identified path; return the complete corrected package.'
        self.summary.setText(message);self.copy.show();self.create.setEnabled(False)

    def copy_error(self):QApplication.clipboard().setText(self.error)
    def accept_project(self):
        if self.validated_revision==self.revision and self.result_project:self.accept()

    def open_project(self,path=None):
        if isinstance(path,bool) or not path:path,_=QFileDialog.getOpenFileName(self,'Open ATS 3 project','','ATS project (*.ats3)')
        if not path:return
        try:
            data=json.loads(Path(path).read_text(encoding='utf-8'))
            if data.get('project_format')!=2:raise ValueError('Expected an ATS 3.0 project (project_format 2).')
            project=Project.load(path)
            self.result_project=project;self.spec=build_spec(project.effective_package(),project.images,project.settings());self.accept()
        except Exception as exc:self.show_error(str(exc))

    def done(self,result):
        self.timer.stop()
        if self.worker and self.worker.isRunning():self.worker.requestInterruption();self.worker.wait()
        super().done(result)

class ExportDialog(Dialog):
    def __init__(self,project,parent=None):
        super().__init__(parent);self.project=project;self.worker=None;self.started=0;self.eta=StageETA();self.result=None
        self.setWindowTitle('Export video');self.resize(550,580);self.setMinimumSize(440,400)
        box=QWidget();v=QVBoxLayout(box);v.setSpacing(16)
        v.addWidget(label('Export video',heading=True));p=project.package
        v.addWidget(label(f'{project.name}\n{FORMATS[project.overrides.get("orientation",project.orientation)][0]} · {p.fps} fps · {human_time(p.audio_duration)} · MP4 (H.264 + AAC)',True))
        self.tier=ClickCombo();self.tier.addItems(['HD','Full HD','4K']);self.tier.setCurrentIndex(1)
        self.quality=ClickCombo();self.quality.addItems(['Fast','Higher quality'])
        self.framing=ClickCombo();self.framing.addItems(['Fill frame (crop)','Fit entire image']);self.framing.setCurrentIndex(0 if project.overrides.get('framing','FILL')=='FILL' else 1)
        for title,w in [('Resolution',self.tier),('Quality',self.quality),('Framing',self.framing)]:v.addWidget(label(title,True));v.addWidget(w)
        safe=''.join(c for c in project.name if c not in '<>:"/\\|?*').strip() or 'ATS video'
        self.path=QLineEdit(str(Path.home()/'Videos'/(safe+'.mp4')));row=QHBoxLayout();row.addWidget(self.path);row.addWidget(button('Browse',self.browse));v.addLayout(row)
        v.addWidget(label('Preview uses the same scene compositor. Encoding and resolution can cause small differences.',True))
        self.progress=QProgressBar();self.progress.setRange(0,1000);self.progress.setTextVisible(False);v.addWidget(self.progress)
        self.status=label('',True);v.addWidget(self.status)
        actions=QHBoxLayout();self.cancel=button('Cancel',self.cancel_export);actions.addWidget(self.cancel);actions.addStretch();self.export=button('Export MP4',self.start_export,True);actions.addWidget(self.export);v.addLayout(actions)
        root=QVBoxLayout(self);root.addWidget(scroll(box));self.clock=QTimer(self);self.clock.setInterval(1000);self.clock.timeout.connect(self.tick)
        self.stage='';self.percent=0.;self.detail='';self.remaining=None

    def browse(self):
        path,_=QFileDialog.getSaveFileName(self,'Save video',self.path.text(),'MP4 (*.mp4)')
        if path:self.path.setText(path)

    def start_export(self):
        if self.worker:return
        target=Path(self.path.text())
        if target.exists():self.status.setText('That file already exists. Choose another filename.');return
        target.parent.mkdir(parents=True,exist_ok=True)
        settings=self.project.settings(tier=self.tier.currentIndex(),quality='STANDARD' if self.quality.currentIndex()==0 else 'MAX',framing='FILL' if self.framing.currentIndex()==0 else 'FIT')
        self.worker=ExportWorker(self.project.effective_package(),self.project.images,Path(self.project.narration),target,settings)
        self.worker.progress_changed.connect(self.update_progress);self.worker.completed.connect(self.completed);self.worker.failed.connect(self.failed);self.worker.stopped.connect(lambda:self.failed('Export cancelled.'))
        self.worker.finished.connect(self.worker_finished)
        for w in (self.tier,self.quality,self.framing,self.path,self.export):w.setEnabled(False)
        self.started=time.monotonic();self.clock.start();self.worker.start()

    def update_progress(self,stage,percent,detail):
        self.stage,self.percent,self.detail=stage,percent,detail;self.remaining=self.eta.update(percent,time.monotonic())
        old=getattr(self,'_progress_anim',None)
        if old:old.stop()
        if reduced_motion():self.progress.setValue(round(percent*10))
        else:
            a=QPropertyAnimation(self.progress,b'value',self);a.setDuration(160);a.setStartValue(self.progress.value());a.setEndValue(round(percent*10));a.setEasingCurve(QEasingCurve.OutCubic);self._progress_anim=a;a.start()
        self.tick()

    def tick(self):
        elapsed=human_time(time.monotonic()-self.started);eta=human_time(self.remaining) if self.remaining is not None else 'Calculating…'
        self.status.setText(f'{self.stage or "Preparing"} · {self.percent:.0f}%\nElapsed {elapsed} · Stage remaining {eta}')

    def completed(self,result):self.result=result;self.progress.setValue(1000);self.clock.stop();self.status.setText('Export complete. Video and report saved.');self.cancel.setText('Done')
    def failed(self,message):self.clock.stop();self.status.setText(message);self.cancel.setText('Close')
    def worker_finished(self):
        worker=self.worker;self.worker=None;worker.deleteLater()
        if self.result:self.export.setText('Open video');self.export.setEnabled(True);self.export.clicked.disconnect();self.export.clicked.connect(self.open_result)
        else:self.export.setEnabled(True)
    def open_result(self):
        from PySide6.QtGui import QDesktopServices
        from PySide6.QtCore import QUrl
        QDesktopServices.openUrl(QUrl.fromLocalFile(self.path.text()))
    def cancel_export(self):
        if self.worker:self.worker.cancel_event.set();self.cancel.setEnabled(False);self.status.setText('Cancelling…')
        else:self.reject()
    def reject(self):
        if self.worker:self.cancel_export()
        else:super().reject()

"""One Pro preview path and a view/seek-only timeline."""
import math
