def source_tree(module):
    return ast.parse(inspect.getsource(module))


def literal(node):
    return ast.literal_eval(node)


def comparison_bound(tree, variable, op):
    matches=[]
    for n in ast.walk(tree):
        if isinstance(n, ast.Compare) and isinstance(n.left,ast.Name) and n.left.id==variable:
            for operation, rhs in zip(n.ops,n.comparators):
                if isinstance(operation,op):
                    try: matches.append(literal(rhs))
                    except (ValueError,TypeError): pass
    assert matches, (variable,op)
    return matches[0]


class TraceChecker:
    """Exercise validator declarations without claiming to validate the probes."""
    def __init__(self): self.fields={}; self.objects={}; self.errors=[]
    def error(self,*args): pass
    def object(self,value,path,allowed):
        self.objects[path]=sorted(allowed)
        if not isinstance(value,dict): value={}
        for key in allowed:
            if key not in value: value[key]=self.seed(path,key)
        return value
    def seed(self,path,key):
        if key in {'format','direction','finish','style','audio','master','caption_style','motion_config','transition_config','look_override','focus','ending','auto_direct','ambience','music'}:return {}
        if key=='sfx': return {} if path=='$.audio' else [{}]
        if key=='scenes':return [{}]
        if key=='words':return [{'index':1,'start':0,'end':1,'text':'Test'}]
        if key=='captions':return []
        if key=='overlays':return [{}]
        if key=='points':return [[.2,.2],[.4,.2],[.4,.4],[.2,.4]]
        if key=='emphasis':return [1]
        if key=='moments':return []
        if key=='index':return 1
        if key in {'id','scene_id','image_id'}:return '001'
        if key=='type':return 'PHOTO_NOTE' if path.startswith('$.overlays') else 'HARD_CUT'
        if key=='variant':return 1
        if key=='orientation':return 'VERTICAL'
        if key=='aspect_ratio':return '9:16'
        if key=='audio_duration':return 10
        if key=='end':return 10
        if key=='text':return 'Test'
        return 0
    def array(self,value,path):
        self.fields[path]={'type':'array'}
        return value if isinstance(value,list) else []
    def number(self,value,path,lo,hi,integer=False):
        self.fields[path]={'type':'integer' if integer else 'number','min':lo,'max':hi}
    def enum(self,value,path,allowed):
        self.fields[path]={'type':'string','enum':sorted(allowed)}
    def boolean(self,value,path): self.fields[path]={'type':'boolean'}
    def string(self,value,path,max_chars=120): self.fields[path]={'type':'string','max_length':max_chars}


def normalized(path): return re.sub(r'\[\d+\]','[]',path)


def get_defaults(module):
    result={}
    for n in ast.walk(source_tree(module)):
        if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and n.func.attr=='get' and len(n.args)==2:
            try:
                key=literal(n.args[0]);value=literal(n.args[1])
                if isinstance(key,str) and not isinstance(value,(dict,list,set)):result.setdefault(key,[]).append(value)
            except (ValueError,TypeError):pass
    return {k:list(dict.fromkeys(v)) for k,v in result.items()}


def build_contract():
    from ats_studio import __version__, capabilities, pro_schema, schema, product, moments, visual_director, pro_audio, pro_spec, caption_presets
    cap=capabilities.current_capabilities()
    trace=TraceChecker()
    raw={'format':{},'direction':{},'caption_style':{},'scenes':[{}],'words':[{'index':1}], 'overlays':[{}]}
    pro_schema._validate_v2(raw,trace)
    pro_schema._validate_product_fields(raw,trace)  # fields added by caption object above
    objects={normalized(p):v for p,v in trace.objects.items()}
    constraints={normalized(p):v for p,v in trace.fields.items()}
    # Remove validator compatibility fields that the product wrapper rejects.
    banned=['$.auto_direct','$.audio.music','$.audio.ambience','$.audio.sfx.pack','$.audio.sfx.density',
            '$.caption_style.chunk_words','$.caption_style.safe_zone','$.scenes[].motion_config.shake']
    # Verify these bans remain present in the real wrapper; fingerprint guards details.
    wrapper=inspect.getsource(product.parse_script)
    for token in ('auto_direct',"('music','ambience')","('pack','density')","('chunk_words','safe_zone')", "'shake'"):
        assert token in wrapper, f'Product ban changed: {token}; review generation.'
    for path in list(objects):
        if any(path==b or path.startswith(b+'.') for b in banned): objects.pop(path)
    for path,fields in objects.items():
        objects[path]=[k for k in fields if path+'.'+k not in banned]
    for path in list(constraints):
        if any(path==b or path.startswith(b+'.') for b in banned): constraints.pop(path)
    # The core validator owns words/captions and mandatory package scalars.
    objects['$.words[]']=sorted(schema.WORD_FIELDS)
    objects['$.captions[]']=sorted(schema.CAPTION_FIELDS)
    objects['$']=sorted(set(cap['required_fields']['package'])|set(cap['optional_fields']['package']))
    constraints.update({'$.schema':{'type':'string','enum':cap['supported_schema_versions']},
        '$.project_title':{'type':'string','nonempty':True},'$.audio_duration':{'type':'number','exclusive_min':0},
        '$.fps':{'type':'integer','min':cap['limits']['fps'][0],'max':cap['limits']['fps'][1]},
        '$.scenes':{'type':'array','min_items':1},'$.words':{'type':'array'},'$.captions':{'type':'array'},
        '$.scenes[].motion':{'type':'string','enum':cap['enums']['motions']},
        '$.scenes[].transition':{'type':'string','enum':cap['enums']['transitions']}})
    for key in ('id','image_id','voice_text'):constraints['$.scenes[].'+key]={'type':'string'}
    for key in ('start','end'):constraints['$.scenes[].'+key]={'type':'number','min':0}
    for key in schema.WORD_FIELDS:constraints['$.words[].'+key]={'type':'integer' if key=='index' else 'number' if key in {'start','end'} else 'string'}
    for key in schema.CAPTION_FIELDS:constraints['$.captions[].'+key]={'type':'integer' if key.endswith('_index') else 'number' if key in {'start','end'} else 'string'}
    constraints['$.caption_style.text_color']=constraints['$.caption_style.accent_color']={'type':'string','pattern':'#[0-9a-fA-F]{6}'}
    constraints['$.format.aspect_ratio']={'type':'string','enum':sorted(v[0] for v in product.FORMATS.values())}
    mtree=source_tree(moments)
    for kind in ('DATE_CARD','CIRCLE'):
        for node in ast.walk(mtree):
            if isinstance(node,ast.Set) and all(isinstance(e,ast.Constant) for e in node.elts):
                fields=set(literal(node))
                if 'word_start_index' in fields and ('text' in fields)==(kind=='DATE_CARD'):
                    objects['$.moments.'+kind]=sorted(fields);break
    date_text_limits=next((literal(n.left),literal(n.comparators[-1])) for n in ast.walk(mtree)
                         if isinstance(n,ast.Compare) and len(n.ops)==2 and isinstance(n.left,ast.Constant)
                         and any(isinstance(c,ast.Call) and isinstance(c.func,ast.Name) and c.func.id=='len' for c in n.comparators))
    dimmax=next(literal(n.comparators[-1]) for n in ast.walk(mtree) if isinstance(n,ast.Compare) and len(n.ops)==2
                and any(isinstance(c,ast.Name) and c.id=='dim' for c in n.comparators))
    area=next(literal(n.comparators[0]) for n in ast.walk(mtree) if isinstance(n,ast.Compare) and isinstance(n.left,ast.BinOp)
              and ast.unparse(n.left)=='w * h')
    seedmax=next(literal(n.comparators[-1]) for n in ast.walk(source_tree(visual_director)) if isinstance(n,ast.Compare)
                 and any(isinstance(c,ast.Attribute) and c.attr=='seed' for c in n.comparators))
    constraints['$.style.seed'].update(min=0,max=seedmax,schema_min=constraints['$.style.seed']['min'],schema_max=constraints['$.style.seed']['max'])
    vd=asdict(visual_director.VisualDirectorSettings())
    capfactor=next(literal(n.value) for n in ast.walk(source_tree(visual_director)) if isinstance(n,ast.Assign)
                   and any(isinstance(t,ast.Name) and t.id=='mode_factor' for t in n.targets))
    cap45=next(literal(n.left) for n in ast.walk(source_tree(visual_director)) if isinstance(n,ast.BinOp)
                and isinstance(n.left,ast.Constant) and isinstance(n.right,ast.Call) and isinstance(n.right.func,ast.Name) and n.right.func.id=='min')
    spacing=next(literal(n.comparators[0]) for n in ast.walk(source_tree(pro_audio)) if isinstance(n,ast.Compare)
                 and isinstance(n.left,ast.Call) and isinstance(n.left.func,ast.Name) and n.left.func.id=='abs')
    required={'$':cap['required_fields']['package'],'$.scenes[]':cap['required_fields']['scene'],
              '$.words[]':cap['required_fields']['word'],'$.captions[]':cap['required_fields']['caption'],
              '$.caption_style':cap['required_fields']['caption_style'],'$.format':['orientation','aspect_ratio'],
              '$.scenes[].motion_config.focus':['x','y'],'$.scenes[].sfx[]':['id'],
              '$.overlays[]':['id','type','start','end'],
              '$.moments.DATE_CARD':['type','text','word_start_index','word_end_index'],
              '$.moments.CIRCLE':['type','scene_id','box','word_start_index','word_end_index']}
    defaults={**get_defaults(product),**get_defaults(pro_spec),**get_defaults(pro_audio),**get_defaults(moments)}
    return {'version':__version__,'capabilities':cap,'objects':dict(sorted(objects.items())),
        'constraints':dict(sorted(constraints.items())),'required':required,'defaults_detected':defaults,
        'director':{'defaults':vd,'mode_factor':capfactor,'shorter_scene_fraction':cap45,
            'fancy':sorted(visual_director.FANCY),'subtle':sorted(visual_director.TRANSITIONS-visual_director.FANCY)},
        'moments':{'date_text':list(date_text_limits),'dim':[0,dimmax],
            'dim_default':moments.validate_moments.__code__.co_consts[0] if False else get_defaults(moments)['dim'][0],
            'circle_min_side':comparison_bound(mtree,'w',ast.Lt),'circle_max_area':area},
        'sfx_spacing_ms':spacing,'caption_profiles':{k:{p:v for p,v in d.items() if p in {'font','size','accent','animation','caps'}} for k,d in caption_presets.PROFILES.items()},
        'source_sha256':{name:hashlib.sha256((ROOT/'ats_studio'/name).read_bytes()).hexdigest() for name in
            ['__init__.py','schema.py','pro_schema.py','pro_spec.py','product.py','visual_director.py','caption_presets.py',
             'project_settings.py','moments.py','finishing.py','music.py','pro_audio.py','capabilities.py','pro_compositor.py','renderer.py','media.py']}}


def join(values):return ', '.join(values)


def constraint_text(c):
    if not c:return 'object'  # untyped parent objects are separately declared
    text=c['type']
    if 'enum' in c:text+=': '+join(c['enum'])
    if 'min' in c and 'max' in c:text+=f" {c['min']}..{c['max']}"
    elif 'min' in c:text+=f" >={c['min']}"
    if 'exclusive_min' in c:text+=f" >{c['exclusive_min']}"
    if 'max_length' in c:text+=f" <= {c['max_length']} characters"
    if c.get('nonempty'):text+=' nonempty'
    if 'pattern' in c:text+=' '+c['pattern']
    if 'min_items' in c:text+=f" >= {c['min_items']} items"
    return text


def field_rows(contract):
    rows=[]
    for path,fields in contract['objects'].items():
        for key in fields:
            full=path+'.'+key
            c=contract['constraints'].get(full)
            if not c and full in contract['objects']:c={'type':'object'}
            if not c and full+'[]' in contract['objects']:c={'type':'array'}
            if not c and path.startswith('$.moments'):
                if key=='dim':c={'type':'number','min':0,'max':contract['moments']['dim'][1]}
                elif key=='box':c={'type':'array [x,y,w,h]'}
                elif key.endswith('_index'):c={'type':'integer referencing words[]'}
                else:c={'type':'string'}
            rows.append((full,'R' if key in contract['required'].get(path,[]) else 'O',constraint_text(c)))
    return rows


def core_tables(c):
    cap=c['capabilities'];rows=['FIELD CONTRACT (R parser-required; A author-required; O optional; numbers finite, never booleans).']
    rows+=['Package R: '+join(cap['required_fields']['package'])+'. Package A: format, direction, moments. Package O: style, audio, overlays, ending.',
       'Scene R: '+join(cap['required_fields']['scene'])+'. Scene A: motion, transition. Scene O: motion_config, transition_config, sfx, look_override.',
       'Word R: '+join(cap['required_fields']['word'])+'. Caption R: '+join(cap['required_fields']['caption'])+'.',
       'caption_style R: '+join(cap['required_fields']['caption_style'])+'. O: '+join(cap['optional_fields']['caption_style'])+'.',
       'All other object keys (and no others):']
    for path,fields in c['objects'].items():
        if path not in {'$','$.scenes[]','$.words[]','$.captions[]','$.caption_style'}:
            rows.append(path.replace('$.','')+': '+join(fields)+'.')
    rows+=['ENUMS (case-sensitive):']
    for label,key in [('Motion','motions'),('Transition','transitions'),('Preset','caption_presets'),('Font','fonts'),('Style','styles'),('Look','looks'),('Ease','easings'),('Overlay type','overlay_types'),('Overlay style','overlay_styles'),('SFX','sfx')]:
        vals=cap['enums'][key]
        if key=='motions':vals=[v for v in vals if v not in {'STATIC_HOLD','SLOW_PULL_OUT','IMPACT_PUNCH_IN','SUBTLE_PARALLAX'}]
        rows.append(label+': '+join(vals)+'.')
    rows.append('Format pairs: '+'; '.join(k+'/'+v['aspect_ratio'] for k,v in cap['formats'].items())+'.')
    # Numeric declarations grouped by identical limits; values come from actual checks.
    grouped={}
    for path,v in c['constraints'].items():
        if v['type'] in {'number','integer'} and 'max' in v:
            grouped.setdefault((v['type'],v.get('min'),v['max']),[]).append(path.replace('$.',''))
    rows.append('NUMERIC LIMITS:')
    for (kind,lo,hi),paths in grouped.items():rows.append(join(paths)+f': {kind} {lo}..{hi}.')
    # Remaining small enums are validator-traced, not manually typed.
    for path in ('$.direction.energy','$.caption_style.position','$.caption_style.background','$.caption_style.animation','$.scenes[].transition_config.direction','$.audio.master.mode','$.ending.mode'):
        rows.append(path.replace('$.','')+': '+join(c['constraints'][path]['enum'])+'.')
    rows.append('SUBTLE transitions: '+join(c['director']['subtle'])+'. FANCY: '+join(c['director']['fancy'])+'.')
    return '\n'.join(rows)


def generate_artifacts(c=None):
    c=c or build_contract();v=c['version'];template=(OUT/'MASTER_PROMPT.template.txt').read_text(encoding='utf-8')
    mapping={'VERSION':v,'TABLES':core_tables(c),'CAP45':str(c['director']['shorter_scene_fraction']),
       'MIN_EFFECT':str(c['director']['defaults']['min_duration']),'MAX_EFFECT':str(c['director']['defaults']['max_duration']),
       'MODE_FACTORS':'/'.join(str(c['director']['mode_factor'][x]) for x in ('SUBTLE','BALANCED','HIGH_ENERGY')),
       'CIRCLE_SIDE':str(c['moments']['circle_min_side']),'CIRCLE_AREA':str(c['moments']['circle_max_area']),
       'DIM_MAX':str(c['moments']['dim'][1]),'DIM_DEFAULT':str(c['moments']['dim_default']),
       'DATE_MAX':str(c['moments']['date_text'][1]),'SPACING':str(c['sfx_spacing_ms']),
       'JSON_BYTES':str(c['capabilities']['limits']['json_bytes'])}
    for key,value in mapping.items():template=template.replace('{{'+key+'}}',value)
    assert '{{' not in template,'Unfilled template token'
    assert len(template.split())<=3500, f'Core is {len(template.split())} words (maximum 3500)'
    pinned=(f'Always follow ATS MASTER PROMPT v{v} (attach MASTER_PROMPT.txt in every new chat). '
       f'Tool 3.0.1 uses ATS_PACKAGE_V2 only. All V1/V3, layered, Remotion and old-mode rules are obsolete. '
       'Never invent fields/enums or timestamps. Never skip required sections: schema, project_title, audio_duration, fps, format, scenes, words, captions, caption_style, direction, moments. '
       'Use final recording and measured word alignment; SRT is not word alignment. Explicitly author every scene motion and transition within the prompt budgets. '
       'Use source-space small-object circles only when certain; spoken meaningful dates get bounded DATE_CARDs. Music is imported in the app. '
       f'Acknowledge ATS v{v} active separately; package answer/file = one compact UTF-8 JSON object, no BOM/fences/prose/trailing newline. '
       'On Copy for ChatGPT, fix only named paths and return the complete JSON. Missing master-prompt text: do not pretend memory contains its contract.')
    assert len(pinned)<=1200
    ref=['# ATS '+v+' — implementation-derived reference','',
       'Generated by tools/generate_master_prompt.py. R = parser-required in its parent; O = optional. The master adds A requirements. Empty optional parent objects use defaults. All numeric fields are finite; booleans are not numbers.',
       '', '| Path | R/O | Type / enum / limit |','|---|---|---|']
    ref += ['| `'+p+'` | '+r+' | '+t.replace('|','\\|')+' |' for p,r,t in field_rows(c)]
    ref+=['','## Contextual defaults extracted from .get calls','',
        'Multiple defaults indicate different execution contexts; the effective product settings below take precedence. Dynamic preset values appear in the profile table. A missing optional parent does not make its child required.',
        '', '| Key | Source defaults |','|---|---|']
    ref+=['| `'+k+'` | `'+json.dumps(val,ensure_ascii=False)+'` |' for k,val in sorted(c['defaults_detected'].items())]
    ref+=['','## Effective product defaults and resolutions','',
           '```json',json.dumps(c['capabilities']['defaults'],indent=2),'```','',
           '| Orientation | Ratio | HD | Full HD | 4K |','|---|---|---|---|---|']
    ref+=['| '+k+' | '+f['aspect_ratio']+' | '+' | '.join(str(w)+'×'+str(h) for w,h in f['tiers'])+' |' for k,f in c['capabilities']['formats'].items()]
    ref+=['','## Fixed creator caption profiles','', '| Preset | Font suggestion | Size @1080×1920 | Accent | Animation | Caps |','|---|---|---|---|---|---|']
    ref+=['| '+k+' | '+str(d['font'])+' | '+str(d['size'])+' | '+d['accent']+' | '+d['animation']+' | '+str(d['caps'])+' |' for k,d in c['caption_profiles'].items()]
    ref+=['', (OUT/'REFERENCE_NOTES.md').read_text(encoding='utf-8')]
    cap=c['capabilities']
    # Current portable capabilities.json can be old-version metadata; don't rewrite it.
    artifacts={'MASTER_PROMPT.txt':template.rstrip()+'\n','PINNED_CORE.txt':pinned+'\n',
       'REFERENCE.md':'\n'.join(ref)+'\n','IMPLEMENTATION_CONTRACT.json':json.dumps(c,ensure_ascii=False,sort_keys=True,indent=2)+'\n'}
    return artifacts


def main():
    p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');args=p.parse_args()
    artifacts=generate_artifacts();drift=[]
    for name,content in artifacts.items():
        path=OUT/name
        if args.check:
            if not path.is_file() or path.read_text(encoding='utf-8')!=content:drift.append(name)
        else:path.write_text(content,encoding='utf-8',newline='\n')
    if drift:raise SystemExit('ATS prompt drift: '+', '.join(drift)+'; regenerate and review before releasing.')
    print(('CHECK PASS' if args.check else 'GENERATED')+f": {len(artifacts['MASTER_PROMPT.txt'].split())} words; {len(artifacts['PINNED_CORE.txt'].strip())} pinned characters")


if __name__=='__main__':main()

