def main():
    groups={}
    for root in SEARCH:
        for p in sorted(root.rglob('CHATGPT_MASTER_PROMPT_ATS*')):
            if not p.is_file():continue
            content=p.read_text(encoding='utf-8-sig');sha=hashlib.sha256(content.encode()).hexdigest()
            g=groups.setdefault(sha,{'sha256':sha,'paths':[],'text':content});g['paths'].append(str(p))
    snap=OUT/'OLD_PROMPTS';snap.mkdir(exist_ok=True)
    report=['# Migration to ATS MASTER PROMPT v3.0.1','',
       'All found named ATS master-prompt versions are audited below, every physical line, including blanks. Identical texts are grouped by SHA256; every original location is retained in OLD_PROMPTS/inventory.json. Historical files were only read.',
       '', 'CHANGE preserves the working part of a mixed line and replaces its obsolete portion. REMOVE removes unsupported instructions, not useful story facts. KEEP means the line remains valid; condensed phrasing is permitted.',
       '', 'Archived STORY_VISUAL_DIRECTOR_GUIDE.md was read at E:/AI/ATS-2.1.0-SOURCE. Its timeline/effect/non-ML constraints remain; V1 import, toggles, strict mode, .atsproj and old UI selectors are removed. Current repo has no file with that exact name.',
       '', '## Sources and complete line audit','']
    inventory=[];counts={'KEEP':0,'CHANGE':0,'REMOVE':0}
    for i,(sha,g) in enumerate(sorted(groups.items()),1):
        name=f'{i:02d}-{sha[:12]}.txt';(snap/name).write_text(g['text'],encoding='utf-8',newline='\n')
        lines=g['text'].splitlines();inventory.append({k:v for k,v in g.items() if k!='text'}|{'snapshot':name,'lines':len(lines)})
        report+=['### Revision '+str(i)+' — '+lines[0],'',f"SHA256 `{sha}` · {len(lines)} lines · {len(g['paths'])} identical copies.",'',
                 '| Line | Decision | Original exact line | Reason |','|---|---|---|---|']
        for n,line in enumerate(lines,1):
            action,reason=decision(line,i);counts[action]+=1
            report.append(f'| {n} | {action} | '+(line.replace('|','\\|').replace('`','&#96;') or '(blank)')+' | '+reason+' |')
    report+=['','## Preserved working invariants','',
       'Final narration authority; measured word/character alignment; SRT is not word alignment; relative timing; decimal half-up frame joins; complete numbered images and sequential independent caption IDs; exact inclusive word ranges/text; full scene theme/registry/end marker; no software/image editing while authoring; one compact UTF-8 object/full consumption; known-source PHOTO_NOTE; evidence visibility; exact supported effects; errors corrected as full objects.',
       '', '## Resolved contradictions','',
       'The historical 3.0.0 Remotion wrapper is not the current 3.0.1 implementation. V1/V3 and layered fields never reach the new prompt. STATIC-all and omitted-director choices are replaced with explicit story decisions. An activation acknowledgement is separate from the JSON-only answer. Maximum capabilities means relevance assessment, not all effects forced into every video. See DECISIONS.md for budgets and gaps.',
       '', f"Inventory: {len(inventory)} distinct texts, {sum(len(g['paths']) for g in inventory)} files, {sum(counts.values())} physical lines; "+', '.join(f'{k} {v}' for k,v in counts.items())+'.']
    (snap/'inventory.json').write_text(json.dumps(inventory,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    (OUT/'MIGRATION_NOTE.md').write_text('\n'.join(report)+'\n',encoding='utf-8',newline='\n')
    print(f'Audited {len(inventory)} distinct revisions, {sum(counts.values())} lines: {counts}')


if __name__=='__main__':main()
